const m = $json.message ?? {};
const text = (m.text ?? '').trim();
const command = text.split(/\s+/)[0].split('@')[0].toLowerCase();

const replies = {
  '/start': `🎬 Pingoo Video جاهز

/video إنشاء فيديو
/status حالة الطلب
/history السجل
/settings الإعدادات
/cancel إلغاء الطلب`,

  '/video': `🎬 أرسل موضوع الفيديو بعد الأمر، مثال:
/video أفضل الأماكن السياحية في السعودية`,

  '/status': `📊 سيتم عرض حالة آخر مهمة هنا.`,

  '/history': `📚 سيتم عرض الفيديوهات السابقة هنا.`,

  '/settings': `⚙️ سيتم حفظ إعدادات اللغة والصوت والمقاس هنا.`,

  '/cancel': `❌ سيتم ربط الإلغاء بالمهمة النشطة.`
};

return [{
  json: {
    chat_id: m.chat?.id,
    telegram_id: m.from?.id,
    username: m.from?.username ?? '',
    first_name: m.from?.first_name ?? '',
    command,
    original_text: text,
    reply: replies[command] ?? 'استخدم /start لعرض الأوامر'
  }
}];
